//! Typed launches of the `s2s-simt` inference kernels.
//!
//! The PTX is generated by cuda-oxide from `crates/s2s-simt/src/infer_kernels.rs`
//! (`scripts/build-simt-ptx.sh`) and checked in, so this crate builds on
//! stable Rust without the cuda-oxide toolchain. The driver JIT-compiles it
//! for the GPU at load time.
//!
//! Each launcher documents the kernel's launch shape; the kernels take raw
//! device pointers, so the shapes and lengths checked here are the only
//! guard against out-of-bounds access.

#![allow(unsafe_code)]

use std::sync::Arc;

use cudarc::driver::{
    CudaContext, CudaFunction, CudaModule, CudaSlice, CudaStream, DriverError, LaunchConfig,
    PushKernelArg,
};
use cudarc::nvrtc::Ptx;
use half::bf16;

const PTX: &str = include_str!("s2s_simt.ptx");
const BLOCK: u32 = 256;
/// Keys per attention split; must match `ATTN_CHUNK` in the kernels.
pub(crate) const ATTN_CHUNK: usize = 256;
/// Largest head dimension the attention kernels support.
pub(crate) const MAX_HEAD_DIM: usize = 256;

fn grid_for(n: usize) -> LaunchConfig {
    LaunchConfig {
        grid_dim: ((n as u32).div_ceil(BLOCK).max(1), 1, 1),
        block_dim: (BLOCK, 1, 1),
        shared_mem_bytes: 0,
    }
}

fn blocks(grid: usize, block: u32) -> LaunchConfig {
    LaunchConfig {
        grid_dim: (grid as u32, 1, 1),
        block_dim: (block, 1, 1),
        shared_mem_bytes: 0,
    }
}

fn check(what: &str, ok: bool) -> Result<(), DriverError> {
    // Shape errors are programming errors in this crate; fail loudly rather
    // than launch a kernel that would read or write out of bounds.
    assert!(ok, "s2s-gpu kernel launch: bad shape for {what}");
    Ok(())
}

/// The loaded kernels.
pub(crate) struct Simt {
    _module: Arc<CudaModule>,
    rms_norm: CudaFunction,
    rope_interleaved: CudaFunction,
    kv_append: CudaFunction,
    attn_decode_partial: CudaFunction,
    attn_decode_combine: CudaFunction,
    glu_silu: CudaFunction,
    add_inplace: CudaFunction,
    f32_to_bf16: CudaFunction,
}

impl std::fmt::Debug for Simt {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("Simt { .. }")
    }
}

impl Simt {
    pub fn load(ctx: &Arc<CudaContext>) -> Result<Self, DriverError> {
        let m = ctx.load_module(Ptx::from_src(PTX))?;
        Ok(Self {
            rms_norm: m.load_function("rms_norm")?,
            rope_interleaved: m.load_function("rope_interleaved")?,
            kv_append: m.load_function("kv_append")?,
            attn_decode_partial: m.load_function("attn_decode_partial")?,
            attn_decode_combine: m.load_function("attn_decode_combine")?,
            glu_silu: m.load_function("glu_silu")?,
            add_inplace: m.load_function("add_inplace")?,
            f32_to_bf16: m.load_function("f32_to_bf16")?,
            _module: m,
        })
    }

    /// `y = rmsnorm(x) * alpha` for one row of `d`.
    pub fn rms_norm(
        &self,
        s: &CudaStream,
        x: &CudaSlice<f32>,
        alpha: &CudaSlice<f32>,
        y: &mut CudaSlice<f32>,
        eps: f32,
    ) -> Result<(), DriverError> {
        let d = alpha.len();
        check("rms_norm", x.len() == d && y.len() == d)?;
        let d32 = d as u32;
        let mut b = s.launch_builder(&self.rms_norm);
        b.arg(x).arg(alpha).arg(y).arg(&d32).arg(&eps);
        unsafe { b.launch(blocks(1, BLOCK)) }.map(|_| ())
    }

    /// Interleaved RoPE on the first `npairs` pairs of `x` (q and k of a
    /// fused qkv: `npairs = d`).
    pub fn rope_interleaved(
        &self,
        s: &CudaStream,
        x: &mut CudaSlice<f32>,
        cos: &CudaSlice<f32>,
        sin: &CudaSlice<f32>,
        npairs: usize,
    ) -> Result<(), DriverError> {
        let half = cos.len();
        check(
            "rope",
            sin.len() == half && half > 0 && x.len() >= 2 * npairs,
        )?;
        let (np, h) = (npairs as u32, half as u32);
        let mut b = s.launch_builder(&self.rope_interleaved);
        b.arg(x).arg(cos).arg(sin).arg(&np).arg(&h);
        unsafe { b.launch(grid_for(npairs)) }.map(|_| ())
    }

    /// Copy k and v of `qkv` (`[3 d]`) into cache slot `slot`.
    #[allow(clippy::too_many_arguments)]
    pub fn kv_append(
        &self,
        s: &CudaStream,
        qkv: &CudaSlice<f32>,
        kc: &mut CudaSlice<f32>,
        vc: &mut CudaSlice<f32>,
        d: usize,
        head_dim: usize,
        cap: usize,
        slot: usize,
    ) -> Result<(), DriverError> {
        check(
            "kv_append",
            qkv.len() == 3 * d && kc.len() == d * cap && vc.len() == d * cap && slot < cap,
        )?;
        let (d32, hd, c, sl) = (d as u32, head_dim as u32, cap as u32, slot as u32);
        let mut b = s.launch_builder(&self.kv_append);
        b.arg(qkv)
            .arg(kc)
            .arg(vc)
            .arg(&d32)
            .arg(&hd)
            .arg(&c)
            .arg(&sl);
        unsafe { b.launch(grid_for(d)) }.map(|_| ())
    }

    /// Decode attention of the query in `qkv[..d]` over the first `n` cache
    /// slots, into `out: [d]`. `po`/`pml` are split scratch buffers with room
    /// for `heads * ceil(cap / 256)` splits.
    #[allow(clippy::too_many_arguments)]
    pub fn attn_decode(
        &self,
        s: &CudaStream,
        qkv: &CudaSlice<f32>,
        kc: &CudaSlice<f32>,
        vc: &CudaSlice<f32>,
        po: &mut CudaSlice<f32>,
        pml: &mut CudaSlice<f32>,
        out: &mut CudaSlice<f32>,
        heads: usize,
        head_dim: usize,
        cap: usize,
        n: usize,
    ) -> Result<(), DriverError> {
        let d = heads * head_dim;
        let nsplit = n.div_ceil(ATTN_CHUNK);
        check(
            "attn_decode",
            n >= 1
                && n <= cap
                && head_dim <= MAX_HEAD_DIM
                && qkv.len() >= d
                && kc.len() == d * cap
                && vc.len() == d * cap
                && po.len() >= heads * nsplit * head_dim
                && pml.len() >= heads * nsplit * 2
                && out.len() == d,
        )?;
        let scale = 1.0f32 / (head_dim as f32).sqrt();
        let (hd, c, n32, ns) = (head_dim as u32, cap as u32, n as u32, nsplit as u32);
        let mut b = s.launch_builder(&self.attn_decode_partial);
        b.arg(qkv)
            .arg(kc)
            .arg(vc)
            .arg(&mut *po)
            .arg(&mut *pml)
            .arg(&hd)
            .arg(&c)
            .arg(&n32)
            .arg(&ns)
            .arg(&scale);
        unsafe { b.launch(blocks(heads * nsplit, BLOCK)) }?;
        let mut b = s.launch_builder(&self.attn_decode_combine);
        b.arg(&*po).arg(&*pml).arg(out).arg(&hd).arg(&ns);
        let threads = (head_dim as u32).div_ceil(32) * 32;
        unsafe { b.launch(blocks(heads, threads)) }.map(|_| ())
    }

    /// `h = silu(y[..hidden]) * y[hidden..]`.
    pub fn glu_silu(
        &self,
        s: &CudaStream,
        y: &CudaSlice<f32>,
        h: &mut CudaSlice<f32>,
    ) -> Result<(), DriverError> {
        let hidden = h.len();
        check("glu_silu", y.len() == 2 * hidden)?;
        let h32 = hidden as u32;
        let mut b = s.launch_builder(&self.glu_silu);
        b.arg(y).arg(h).arg(&h32);
        unsafe { b.launch(grid_for(hidden)) }.map(|_| ())
    }

    /// `x += a * scale` (or `x += a`).
    pub fn add_inplace(
        &self,
        s: &CudaStream,
        x: &mut CudaSlice<f32>,
        a: &CudaSlice<f32>,
        scale: Option<&CudaSlice<f32>>,
    ) -> Result<(), DriverError> {
        let n = x.len();
        check(
            "add_inplace",
            a.len() == n && scale.is_none_or(|s| s.len() == n),
        )?;
        let (n32, has) = (n as u32, scale.is_some() as u32);
        let mut b = s.launch_builder(&self.add_inplace);
        b.arg(x).arg(a).arg(scale.unwrap_or(a)).arg(&n32).arg(&has);
        unsafe { b.launch(grid_for(n)) }.map(|_| ())
    }

    /// `y = bf16(x)`.
    pub fn f32_to_bf16(
        &self,
        s: &CudaStream,
        x: &CudaSlice<f32>,
        y: &mut CudaSlice<bf16>,
    ) -> Result<(), DriverError> {
        let n = x.len();
        check("f32_to_bf16", y.len() == n)?;
        let n32 = n as u32;
        let mut b = s.launch_builder(&self.f32_to_bf16);
        b.arg(x).arg(y).arg(&n32);
        unsafe { b.launch(grid_for(n)) }.map(|_| ())
    }
}
